// Ciclo 8h/18h (seção 4): sem resposta em 8h -> reenvia lembrete; mais 18h
// (26h total) sem resposta -> encerra o ciclo, sem ação automática.
function diferencaHoras(a, b) { return (a.getTime() - b.getTime()) / (1000*60*60); }
function avaliarPendenciaIdentificacao({ agora, pendencia }) {
  const primeiraPergunta = new Date(pendencia.primeiraPerguntaEm);
  const horasDecorridas = diferencaHoras(agora, primeiraPergunta);
  if (!pendencia.lembreteEnviado) {
    if (horasDecorridas >= 8) return { acao: 'reenviar_lembrete' };
    return { acao: 'nenhuma' };
  }
  if (horasDecorridas >= 26) return { acao: 'encerrar_sem_resposta' };
  return { acao: 'nenhuma' };
}

function parseBinaryJson(item) {
  if (!item || !item.binary || !item.binary.data) return {};
  return JSON.parse(Buffer.from(item.binary.data.data, 'base64').toString('utf8'));
}
const pendencias = parseBinaryJson($input.first());
const agora = new Date();

const saida = [];
for (const [chave, p] of Object.entries(pendencias)) {
  if (p.resolvida) continue;
  const resultado = avaliarPendenciaIdentificacao({ agora, pendencia: p });
  if (resultado.acao !== 'nenhuma') {
    saida.push({ json: { chave, pendencia: p, acao: resultado.acao, todasPendencias: pendencias } });
  }
}
return saida;

const enviado = $input.first().json;
const origem = $('Avaliar pendências (8h/18h)').first().json;
const pendencias = { ...origem.todasPendencias };
pendencias[origem.chave] = { ...pendencias[origem.chave], lembreteEnviado: true, mensagemIdLembrete: enviado.message_id || (enviado.result && enviado.result.message_id) || null };
return [{ json: { pendencias } }];

const origem = $('Avaliar pendências (8h/18h)').first().json;
const pendencias = { ...origem.todasPendencias };
pendencias[origem.chave] = { ...pendencias[origem.chave], resolvida: true, statusFinal: 'encerrado_sem_resposta' };
return [{ json: { pendencias } }];

// Consolida todas as atualizações desta execução (podem ser várias pendências
// tratadas na mesma varredura) num único pendencias_identificacao.json.
const itens = $input.all().map((i) => i.json);
let consolidado = {};
for (const it of itens) {
  consolidado = { ...consolidado, ...it.pendencias };
}
return [{ json: {}, binary: { data: { data: Buffer.from(JSON.stringify(consolidado, null, 2)).toString('base64'), mimeType: 'application/json', fileName: 'pendencias_identificacao.json' } } }];

// Correlaciona a resposta da Michelle à pendência certa (seção 4, CORRIGIDO —
// commit 3db5653): reply é a forma principal. Sem reply + 2 ou mais pendências
// abertas -> NUNCA adivinhar, pede reply explícito de novo.
function correlacionarRespostaMichelle(mensagemRecebida, pendencias) {
  const abertas = Object.entries(pendencias || {}).filter(([, p]) => !p.resolvida);
  if (mensagemRecebida.replyToMessageId) {
    const chave = abertas.map(([k]) => k).find(
      (k) => pendencias[k].mensagemIdOriginal === mensagemRecebida.replyToMessageId || pendencias[k].mensagemIdLembrete === mensagemRecebida.replyToMessageId
    );
    if (chave) return { resultado: 'correlacionada', chaveCobranca: chave };
  }
  if (abertas.length === 0) return { resultado: 'nenhuma_pendencia' };
  if (abertas.length === 1) return { resultado: 'correlacionada', chaveCobranca: abertas[0][0] };
  return { resultado: 'ambiguo_pedir_reply', chavesAbertas: abertas.map(([k]) => k) };
}

function parseBinaryJson(item) {
  if (!item || !item.binary || !item.binary.data) return {};
  return JSON.parse(Buffer.from(item.binary.data.data, 'base64').toString('utf8'));
}
const pendencias = parseBinaryJson($('Ler pendencias_identificacao.json (resposta)').first());
const msg = $('Telegram Trigger').first().json.message || {};
const mensagemRecebida = { replyToMessageId: msg.reply_to_message && msg.reply_to_message.message_id, texto: (msg.text || '').trim() };

const correlacao = correlacionarRespostaMichelle(mensagemRecebida, pendencias);
return [{ json: { correlacao, mensagemRecebida, pendencias, chatId: msg.chat && msg.chat.id } }];

// 2+ pendências abertas e sem reply válido — reenvia a pergunta de CADA uma
// pedindo reply explícito (seção 4, correção: nunca adivinhar).
const d = $input.first().json;
return d.correlacao.chavesAbertas.map((chave) => ({ json: { chatId: d.chatId, chave, pendencia: d.pendencias[chave] } }));

// Interpreta o texto livre da resposta da Michelle: tenta achar, por
// comparação normalizada (substring), um nome/fornecedor da planilha que
// bata com o que ela escreveu. Escolha de implementação (não é IA aqui —
// nesse ponto um humano já desambiguou, um match de texto simples e
// auditável é suficiente; flagado como decisão, ajustável se necessário).
const ExcelJS = require('exceljs');
function normalizar(t) { return t ? String(t).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().trim() : ''; }
function linhaTemPreenchimento(cell) {
  const fill = cell && cell.fill;
  if (!fill || fill.type !== 'pattern' || fill.pattern !== 'solid') return false;
  const argb = fill.fgColor && fill.fgColor.argb;
  return !!argb && argb !== 'FFFFFFFF' && argb !== '00000000';
}
async function lerRoster(nodeName, projetoFixo) {
  const item = $(nodeName).first();
  const buffer = Buffer.from(item.binary.data.data, 'base64');
  const wb = new ExcelJS.Workbook();
  await wb.xlsx.load(buffer);
  const ws = wb.getWorksheet('Notas') || wb.worksheets[0];
  const linhas = [];
  ws.eachRow({ includeEmpty: false }, (row, rowNumber) => {
    if (rowNumber === 1) return;
    const projetoId = projetoFixo || (linhaTemPreenchimento(row.getCell('L')) ? 'REUNION' : 'AREP');
    linhas.push({ projetoId, linha: rowNumber, colunaB: row.getCell('B').text, colunaC: row.getCell('C').text, colunaG: row.getCell('G').text, colunaH: row.getCell('H').text, nome: (row.getCell('J').text.split(' - ')[1] || row.getCell('H').text) });
  });
  return linhas;
}
const roster = [...(await lerRoster('Box — Download Cost Report S01', null)), ...(await lerRoster('Box — Download Cost Report S02 (Soft Pré)', 'SOFT_PRE'))];

const correlacaoItem = $('Correlacionar resposta da Michelle').first().json;
const textoResposta = normalizar(correlacaoItem.mensagemRecebida.texto);
const candidato = roster.find((r) => textoResposta.includes(normalizar(r.nome)) || textoResposta.includes(normalizar(r.colunaH)));

return [{ json: { ...correlacaoItem, candidato } }];

// Achou — monta o payload pra finalizar a nota (mesmo formato usado por
// fase2_recebimento_validacao.json) e marca a pendência como resolvida.
const d = $input.first().json;
const c = d.candidato;
const chave = d.correlacao.chaveCobranca;
const pendencia = d.pendencias[chave];

const perfis = { AREP: { retranca: 'S01' }, REUNION: { retranca: 'REUNION_S01' }, SOFT_PRE: { retranca: 'SOFT PRE_S02' } };

const payload = {
  projetoId: c.projetoId, linha: c.linha,
  chaveCobranca: perfis[c.projetoId].retranca + '_L' + c.linha,
  tipoDocumento: pendencia.dadosReferencia.tipoDocumento || 'NF',
  numeroNota: pendencia.dadosReferencia.numeroNota || '000000',
  dataEmissao: pendencia.dadosReferencia.dataEmissao,
  dataVencimento: c.colunaG,
  razaoSocialOuNome: pendencia.dadosReferencia.nomeOuRazaoSocial || c.nome,
  codigo: c.colunaB, cargo: c.colunaC,
  perfilRetranca: perfis[c.projetoId].retranca,
};

const pendenciasAtualizadas = { ...d.pendencias };
pendenciasAtualizadas[chave] = { ...pendencia, resolvida: true, statusFinal: 'resolvida_por_michelle' };

return [{ json: { payload, pendenciasAtualizadas } }];
